// Totals values by key and answers queries.
// Usage: deno run --allow-read main.ts <input-file>
//
// The input is handled as raw bytes so that two keys are the same exactly
// when their bytes are the same, whatever the characters are.

const INT64_MIN = -(2n ** 63n);
const INT64_MAX = 2n ** 63n - 1n;
const DECIMAL = /^[+-]?\d+$/;

interface Total {
  sum: bigint;
  overflow: boolean;
}

function isSpace(b: number): boolean {
  return b === 0x20 || b === 0x09 || b === 0x0d;
}

// Splits a line into its space-separated tokens, keeping the raw bytes.
function tokens(line: Uint8Array): Uint8Array[] {
  const out: Uint8Array[] = [];
  let start = -1;
  for (let i = 0; i <= line.length; i++) {
    if (i === line.length || isSpace(line[i])) {
      if (start >= 0) {
        out.push(line.subarray(start, i));
        start = -1;
      }
    } else if (start < 0) {
      start = i;
    }
  }
  return out;
}

// Byte-for-byte string form, usable as a map key and for ASCII numbers.
function latin1(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return s;
}

function splitLines(data: Uint8Array): Uint8Array[] {
  const lines: Uint8Array[] = [];
  let start = 0;
  for (let i = 0; i <= data.length; i++) {
    if (i === data.length || data[i] === 0x0a) {
      if (!(i === data.length && start === data.length)) {
        lines.push(data.subarray(start, i));
      }
      start = i + 1;
    }
  }
  return lines;
}

async function writeAll(bytes: Uint8Array): Promise<void> {
  let off = 0;
  while (off < bytes.length) {
    off += await Deno.stdout.write(bytes.subarray(off));
  }
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: main.ts <input-file>");
    Deno.exit(2);
  }

  const lines = splitLines(await Deno.readFile(path));
  const totals = new Map<string, Total>();

  // Section one: records, up to the first empty line.
  let next = 0;
  for (; next < lines.length; next++) {
    const toks = tokens(lines[next]);
    if (toks.length === 0) break;
    if (toks.length < 2) continue;

    const valueText = latin1(toks[1]);
    if (!DECIMAL.test(valueText)) {
      throw new Error(`line ${next + 1}: not a decimal integer: ${valueText}`);
    }
    const value = BigInt(valueText);

    const key = latin1(toks[0]);
    let total = totals.get(key);
    if (total === undefined) {
      total = { sum: 0n, overflow: false };
      totals.set(key, total);
    }
    if (!total.overflow) {
      total.sum += value;
      if (total.sum < INT64_MIN || total.sum > INT64_MAX) {
        total.overflow = true;
      }
    }
  }

  // Section two: queries, one key per line. Skip the separator and blank lines.
  const encoder = new TextEncoder();
  const chunks: Uint8Array[] = [];
  for (let i = next + 1; i < lines.length; i++) {
    const toks = tokens(lines[i]);
    if (toks.length === 0) continue;

    const total = totals.get(latin1(toks[0]));
    let answer: string;
    if (total === undefined) {
      answer = "=absent\n";
    } else if (total.overflow) {
      answer = "=overflow\n";
    } else {
      answer = `=${total.sum}\n`;
    }
    chunks.push(toks[0], encoder.encode(answer));
  }

  if (chunks.length === 0) return;
  const size = chunks.reduce((n, c) => n + c.length, 0);
  const out = new Uint8Array(size);
  let pos = 0;
  for (const c of chunks) {
    out.set(c, pos);
    pos += c.length;
  }
  await writeAll(out);
}

try {
  await main();
} catch (err) {
  console.error(err instanceof Error ? err.message : err);
  Deno.exit(1);
}

